module tb_TopModule;
    reg [99:0] in;
    wire out_and;
    wire out_or;
    wire out_xor;

    TopModule uut (
        .in(in),
        .out_and(out_and),
        .out_or(out_or),
        .out_xor(out_xor)
    );

    initial begin
        // Test case 1: all zeros
        in = 100'd0;
        #1;
        if (out_and !== 1'b0 || out_or !== 1'b0 || out_xor !== 1'b0) begin
            $display("SELFTEST FAIL: Case all zeros (got and=%b, or=%b, xor=%b)", out_and, out_or, out_xor);
            $finish;
        end

        // Test case 2: all ones
        in = {100{1'b1}};
        #1;
        if (out_and !== 1'b1 || out_or !== 1'b1 || out_xor !== 1'b0) begin
            $display("SELFTEST FAIL: Case all ones (got and=%b, or=%b, xor=%b)", out_and, out_or, out_xor);
            $finish;
        end

        // Test case 3: alternating pattern
        in = 100'h5555555555555555555555555; // 25 hex chars * 4 bits = 100 bits. 0101...
        #1;
        if (out_and !== 1'b0 || out_or !== 1'b1 || out_xor !== 1'b0) begin
            $display("SELFTEST FAIL: Case alternating (got and=%b, or=%b, xor=%b)", out_and, out_or, out_xor);
            $finish;
        end

        // Test case 4: single bit set
        in = 100'h1;
        #1;
        if (out_and !== 1'b0 || out_or !== 1'b1 || out_xor !== 1'b1) begin
            $display("SELFTEST FAIL: Case single bit 0 (got and=%b, or=%b, xor=%b)", out_and, out_or, out_xor);
            $finish;
        end

        // Test case 5: highest bit set
        in = 100'h8000000000000000000000000;
        #1;
        if (out_and !== 1'b0 || out_or !== 1'b1 || out_xor !== 1'b1) begin
            $display("SELFTEST FAIL: Case single bit 99 (got and=%b, or=%b, xor=%b)", out_and, out_or, out_xor);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
